declare(strict_types=1);require_once __DIR__.'/assets/php/bootstrap.php';$slug=trim((string)($_GET['slug']??''));$legacyId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$product=null;if($legacyId&&$slug===''){$s=db()->prepare('SELECT slug FROM producto WHERE id_producto=:id AND activo=TRUE');$s->execute(['id'=>$legacyId]);if($legacySlug=$s->fetchColumn())redirect('producto.php?slug='.rawurlencode($legacySlug));}if($slug!==''&&preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)){$s=db()->prepare('SELECT p.*,c.nombre categoria FROM producto p JOIN categoria_producto c ON c.id_categoria=p.categoria_id WHERE p.slug=:slug AND p.activo=TRUE');$s->execute(['slug'=>$slug]);$product=$s->fetch();}$saved=false;if($product&&!empty($_SESSION['user_id'])){$s=db()->prepare('SELECT 1 FROM wishlist_item WHERE usr_id=:u AND producto_id=:p');$s->execute(['u'=>$_SESSION['user_id'],'p'=>$product['id_producto']]);$saved=(bool)$s->fetchColumn();}if(!$product)http_response_code(404);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($product['nombre']??'Producto no disponible')?> — SIDE B</title><link rel="stylesheet" href="assets/css/variables.css"><link rel="stylesheet" href="assets/css/global.css"><link rel="stylesheet" href="assets/css/components.css"><link rel="stylesheet" href="assets/css/home.css"><link rel="stylesheet" href="assets/css/shop.css?v=2"></head><body><?=sideb_public_header('tienda')?><main class="product-detail"><div class="container product-detail-grid"><?php if(!$product):?><p>Producto no disponible.</p><?php else:?><div class="product-detail-art visual-surface visual-surface--record"><img src="<?=e($product['imagen'])?>" alt="<?=e($product['nombre'])?>"></div><div class="product-detail-copy"><p class="card-kicker"><?=e($product['categoria'])?></p><h1><?=e($product['nombre'])?></h1><div class="product-price-stock"><strong><?=cart_money((float)$product['precio'])?></strong><span class="<?=$product['stock']>0?'in-stock':'out-stock'?>"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="m8.5 12 2.2 2.2 4.8-5"/></svg><?=$product['stock']>0?(int)$product['stock'].' unidades disponibles':'Agotado'?></span></div><?php if($product['descripcion']):?><div class="product-description"><p><?=nl2br(e($product['descripcion']))?></p></div><?php endif;?><div class="product-actions"><?php if($product['stock']>0):?><form method="post" action="carrito.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$product['id_producto']?>"><button class="add-cart-button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 4h2l2 11h10l2-8H6M9 20h.01M17 20h.01"/></svg>Añadir al carrito</button></form><?php endif;?><?php if(!empty($_SESSION['user_id'])):?><form method="post" action="guardados.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_product"><input type="hidden" name="product_id" value="<?=(int)$product['id_producto']?>"><input type="hidden" name="return_url" value="producto.php?slug=<?=rawurlencode($slug)?>"><button class="save-product-button<?=$saved?' is-saved':''?>" aria-label="<?=$saved?'Quitar de guardados':'Guardar producto'?>" aria-pressed="<?=$saved?'true':'false'?>" title="<?=$saved?'Quitar de guardados':'Guardar producto'?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3.75A1.75 1.75 0 0 1 7.75 2h8.5A1.75 1.75 0 0 1 18 3.75V22l-6-3.75L6 22V3.75Z"/></svg></button></form><?php endif;?></div><p class="product-physical"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 8 8-4 8 4v9l-8 4-8-4Z"/><path d="m4 8 8 4 8-4M12 12v9"/></svg>Producto físico · Sujeto a disponibilidad</p></div><?php endif;?></div></main><?=sideb_footer()?></body></html>
